    correctAnswer: 0,
    explanation: 'Custom layouts in Compose are created using the Layout composable. You provide a MeasurePolicy that defines how to measure children and place them. Each child is measured with Constraints and placed at specific positions.',
    codeSnippet: '@Composable\nfun StaggeredGrid(\n    modifier: Modifier = Modifier,\n    rows: Int = 3,\n    content: @Composable () -> Unit\n) {\n    Layout(content = content, modifier = modifier) { measurables, constraints ->\n        val rowWidths = IntArray(rows)\n        val rowHeights = IntArray(rows)\n        val placeables = measurables.mapIndexed { index, measurable ->\n            val placeable = measurable.measure(constraints)\n            val row = index % rows\n            rowWidths[row] += placeable.width\n            rowHeights[row] = maxOf(rowHeights[row], placeable.height)\n            placeable\n        }\n        val width = rowWidths.maxOrNull() ?: constraints.minWidth\n        val height = rowHeights.sum()\n        layout(width, height) {\n            val rowX = IntArray(rows)\n            var y = 0\n            placeables.forEachIndexed { index, placeable ->\n                val row = index % rows\n                placeable.placeRelative(rowX[row], y)\n                rowX[row] += placeable.width\n                if ((index + 1) % rows == 0) y += rowHeights[row]\n            }\n        }\n    }\n}',
    tags: ['compose', 'custom-layout', 'layout', 'measurepolicy'],
