    codeSnippet: '@Composable\nfun TwoPane(\n    first: @Composable () -> Unit,\n    second: @Composable () -> Unit\n) {\n    SubcomposeLayout { constraints ->\n        val firstPlaceables = subcompose("first") { first() }\n            .map { it.measure(constraints) }\n        val firstHeight = firstPlaceables.maxOfOrNull { it.height } ?: 0\n\n        val secondConstraints = constraints.copy(\n            maxHeight = constraints.maxHeight - firstHeight\n        )\n        val secondPlaceables = subcompose("second") { second() }\n            .map { it.measure(secondConstraints) }\n\n        layout(constraints.maxWidth, constraints.maxHeight) {\n            firstPlaceables.forEach { it.placeRelative(0, 0) }\n            secondPlaceables.forEach { it.placeRelative(0, firstHeight) }\n        }\n    }\n}',
