    codeSnippet: '// Simplified concept using detectDragGesturesAfterLongPress\n@Composable\nfun ReorderableList(items: List<String>, onMove: (Int, Int) -> Unit) {\n    val listState = rememberLazyListState()\n    var draggedIndex by remember { mutableStateOf<Int?>(null) }\n    var dragOffset by remember { mutableStateOf(0f) }\n\n    LazyColumn(state = listState) {\n        itemsIndexed(items, key = { _, item -> item }) { index, item ->\n            val offset = if (index == draggedIndex) dragOffset else 0f\n            Text(\n                text = item,\n                modifier = Modifier\n                    .offset { IntOffset(0, offset.roundToInt()) }\n                    .pointerInput(Unit) {\n                        detectDragGesturesAfterLongPress(\n                            onDragStart = { draggedIndex = index },\n                            onDrag = { _, dragAmount -> dragOffset += dragAmount.y },\n                            onDragEnd = { draggedIndex = null; dragOffset = 0f }\n                        )\n                    }\n            )\n        }\n    }\n}',
