    codeSnippet: '// With Orbit MVI\n@HiltViewModel\nclass ProfileViewModel @Inject constructor(\n    private val repo: UserRepository\n) : ContainerHost<ProfileState, ProfileSideEffect>, ViewModel() {\n\n    override val container = container<ProfileState, ProfileSideEffect>(ProfileState())\n\n    fun loadProfile() = intent {\n        reduce { state.copy(isLoading = true) }\n        val user = repo.getUser()\n        reduce { state.copy(isLoading = false, user = user) }\n        postSideEffect(ProfileSideEffect.ShowToast("Loaded!"))\n    }\n}\n\n@Composable\nfun ProfileScreen(viewModel: ProfileViewModel = hiltViewModel()) {\n    val state by viewModel.container.stateFlow.collectAsStateWithLifecycle()\n    viewModel.container.sideEffectFlow.collectSideEffect { effect ->\n        when (effect) {\n            is ProfileSideEffect.ShowToast -> showToast(effect.message)\n        }\n    }\n}',
