    codeSnippet: 'class UndoRedoManager<T>(initialState: T) {\n    private val undoStack = mutableListOf<T>()\n    private val redoStack = mutableListOf<T>()\n    private val _currentState = MutableStateFlow(initialState)\n    val currentState: StateFlow<T> = _currentState.asStateFlow()\n\n    fun execute(newState: T) {\n        undoStack.add(_currentState.value)\n        redoStack.clear()\n        _currentState.value = newState\n    }\n\n    fun undo() {\n        if (undoStack.isNotEmpty()) {\n            redoStack.add(_currentState.value)\n            _currentState.value = undoStack.removeLast()\n        }\n    }\n\n    fun redo() {\n        if (redoStack.isNotEmpty()) {\n            undoStack.add(_currentState.value)\n            _currentState.value = redoStack.removeLast()\n        }\n    }\n\n    val canUndo: Boolean get() = undoStack.isNotEmpty()\n    val canRedo: Boolean get() = redoStack.isNotEmpty()\n}',
